{
  "research": [
    {
      "id": "R1",
      "title": "Predictive Uncertainty Under Changing Missingness Patterns",
      "bullets": [
        "Formulated whether changes in feature missingness undermine regression interval calibration, separating missingness shifts from changes in observed covariate distributions.",
        "Led development of a missingness-stratified residual calibration procedure and evaluated interval coverage against pooled calibration under controlled masking mechanisms."
      ]
    },
    {
      "id": "R2",
      "title": "Stabilized Conformal Regression Under Covariate Shift",
      "bullets": [
        "Formulated how unstable density ratio estimates affect weighted conformal regression and led development of a clipping procedure with held-out tuning.",
        "Designed controlled shift experiments and coverage diagnostics, examining interactions among ratio estimation, weight regularization, and conditional interval behavior."
      ]
    }
  ],
  "publications": [
    {
      "id": "P1",
      "title": "Density Ratio Estimation and Coverage Sensitivity in Weighted Conformal Regression"
    },
    {
      "id": "P2",
      "title": "Diagnosing Local Coverage Failures Under Covariate Shift"
    },
    {
      "id": "P3",
      "title": "Clipped Importance Weights for Stabilizing Conformal Regression Intervals"
    },
    {
      "id": "P4",
      "title": "Held-Out Tuning of Weight Clipping in Conformal Regression Under Covariate Shift"
    }
  ],
  "work": [],
  "projects": [
    {
      "id": "T1",
      "title": "Regularized Regression With Correlated Predictors",
      "bullets": [
        "Implemented ridge and lasso regression pipelines with standardized predictors, selecting regularization parameters through cross-validation confined to training data.",
        "Compared prediction error and coefficient stability across correlated feature settings, documenting how penalty choices affected recovery of sparse signals."
      ]
    },
    {
      "id": "T2",
      "title": "Probability Calibration for Binary Classification",
      "bullets": [
        "Implemented sigmoid and isotonic calibration for classifier scores, keeping model fitting, calibration, and final evaluation on separate data partitions.",
        "Compared reliability diagrams, Brier scores, and log loss across calibration methods, examining sensitivity to calibration sample size and class imbalance."
      ]
    },
    {
      "id": "T3",
      "title": "Mixture Models for Overlapping Clusters",
      "bullets": [
        "Implemented expectation maximization for Gaussian mixture models with diagonal and full covariance structures, using multiple initializations to assess optimization sensitivity.",
        "Compared mixture models with k-means on simulated overlapping clusters, evaluating held-out likelihood and agreement with known generating labels."
      ]
    },
    {
      "id": "T4",
      "title": "Bootstrap Intervals for Regression Coefficients",
      "bullets": [
        "Implemented residual and pairs bootstrap procedures for linear regression coefficients, reusing fixed simulation settings to support comparable uncertainty estimates.",
        "Compared empirical coverage and interval width under heteroskedastic errors and influential observations, documenting settings where resampling assumptions were violated."
      ]
    }
  ]
}
